198	// Atomic on POSIX: write to a mkstemp-reserved tmp file, fsync, rename.
199	// mkstemp guarantees uniqueness via a 6-char random suffix + atomic
200	// O_EXCL-style inode reservation, so concurrent plugin instances cannot
201	// collide even under aggressive PID reuse (B13). The tmp lives in the
202	// same directory as `path` so the rename is intra-filesystem.
203	static int write_state_atomic(const struct hybrid_state_v1 *s, const char *path)
204	{
205	    char tmp[PATH_MAX];
206	    int n = g_snprintf(tmp, sizeof(tmp), "%s.tmp.XXXXXX", path);
207	    if (n < 0 || (size_t) n >= sizeof(tmp)) {
208	        fprintf(stderr, "hybrid_handoff: tmp path too long\n");
209	        return -1;
210	    }
211	    int fd = g_mkstemp(tmp);
212	    if (fd < 0) {
213	        perror("hybrid_handoff: g_mkstemp");
214	        return -1;
215	    }
216	    // g_mkstemp creates the file 0600; no further chmod needed.
217	    ssize_t want = (ssize_t) sizeof(*s);
218	    ssize_t got = write(fd, s, sizeof(*s));
219	    if (got != want) {
220	        perror("hybrid_handoff: write");
221	        close(fd);
222	        unlink(tmp);
223	        return -1;
224	    }
225	    fsync(fd);
226	    close(fd);
227	    if (rename(tmp, path) != 0) {
228	        perror("hybrid_handoff: rename");
229	        unlink(tmp);
230	        return -1;
231	    }
232	    return 0;
233	}
