235	// Drain CPU state to outfile_path. pc is computed by the caller (from a
236	// HandoffSite for trigger paths, or 0 for the atexit path which lacks an
237	// insn context). If minstret_override is non-zero, it replaces QEMU's PMU
238	// minstret in the state file (used by drain_at_exit mode to record a
239	// plugin-counted retired-insn total). Does NOT call exit -- caller
240	// decides exit(200) (normal trigger) vs _exit(200) (inside atexit chain).
241	static void drain_state_to_file(unsigned int vcpu_idx, uint64_t pc,
242	                                uint64_t minstret_override)
243	{
244	    VcpuRegs *v = qemu_plugin_scoreboard_find(vcpu_state, vcpu_idx);
245	    resolve_handles(v);
246	    struct hybrid_state_v1 s = {0};
247	    s.magic   = HYBRID_STATE_MAGIC;
248	    s.version = HYBRID_STATE_VERSION;
249	    s.flags   = HYBRID_FLAG_RV64;
250	    s.hart_id = vcpu_idx;
251	    s.priv    = 3;
252	    s.pc      = pc;
253	    for (int i = 0; i < 32; i++) s.gpr[i] = read_reg64(v->gpr[i]);
254	
255	    // Floating-point: only set FP flag if at least one handle was bound,
256	    // i.e. QEMU advertised the FPU feature (D extension).
257	    int has_fp = 0;
258	    for (int i = 0; i < 32; i++) {
259	        s.fpr[i] = read_reg64(v->fpr[i]);
260	        if (v->fpr[i]) has_fp = 1;
261	    }
262	    if (has_fp) s.flags |= HYBRID_FLAG_FP;
263	    s.fcsr = read_reg64(v->fcsr);  // L20: rides HYBRID_FLAG_FP
264	
265	    s.mstatus  = read_reg64(v->mstatus);
266	    s.mepc     = read_reg64(v->mepc);
267	    s.mtvec    = read_reg64(v->mtvec);
268	    s.mcause   = read_reg64(v->mcause);
269	    s.mtval    = read_reg64(v->mtval);
270	    s.mscratch = read_reg64(v->mscratch);
271	    s.medeleg  = read_reg64(v->medeleg);
272	    s.mideleg  = read_reg64(v->mideleg);
273	    s.mip      = read_reg64(v->mip);
274	    s.mie      = read_reg64(v->mie);
275	    s.mcycle   = read_reg64(v->mcycle);
276	    s.minstret = minstret_override ? minstret_override
277	                                   : read_reg64(v->minstret);
278	    s.satp     = read_reg64(v->satp);
279	
280	    for (int i = 0; i < HYBRID_PMP_CFG_NUM; i++)
281	        s.pmpcfg[i] = read_reg64(v->pmpcfg[i]);
282	    for (int i = 0; i < HYBRID_PMP_ADDR_NUM; i++)
283	        s.pmpaddr[i] = read_reg64(v->pmpaddr[i]);
284	
285	    // Vector: only set V flag if QEMU advertised the V extension. vlenb
286	    // bounds the per-register byte count copied into vreg[]. The policy
287	    // helper (hybrid_v_drain_policy) decides SKIP/OK/ABORT from the
288	    // handle truthiness so we don't conflate "stub missing vlenb" with
289	    // "V disabled at runtime"; see include/hybrid/v_drain_policy.h.
290	    s.vstart = read_reg64(v->vstart);
291	    s.vxsat  = read_reg64(v->vxsat);
292	    s.vxrm   = read_reg64(v->vxrm);
293	    s.vcsr   = read_reg64(v->vcsr);
294	    s.vtype  = read_reg64(v->vtype);
295	    s.vl     = read_reg64(v->vl);
296	    s.vlenb  = read_reg64(v->vlenb);
297	    int has_other_v = (v->vstart || v->vxsat || v->vxrm || v->vcsr
298	                       || v->vtype || v->vl);
299	    if (!has_other_v) {
300	        for (int i = 0; i < 32; i++)
301	            if (v->vreg[i]) { has_other_v = 1; break; }
302	    }
303	    HybridVDrainPolicy vpol = hybrid_v_drain_policy(
304	        v->vlenb != NULL, has_other_v, s.vlenb);
305	    if (vpol == HYBRID_V_DRAIN_ABORT) {
306	        if (v->vlenb == NULL)
307	            fprintf(stderr,
308	                    "hybrid_handoff: stub advertised V CSRs/regs but not "
309	                    "vlenb; refusing to drain partial V state\n");
310	        else
311	            fprintf(stderr,
312	                    "hybrid_handoff: vlenb=%" PRIu64 " exceeds the wire-format "
313	                    "ceiling HYBRID_VLEN_BYTES_MAX=%d (VLEN %d); refusing to "
314	                    "truncate V registers\n",
315	                    s.vlenb, HYBRID_VLEN_BYTES_MAX,
316	                    8 * HYBRID_VLEN_BYTES_MAX);
317	        exit(2);
318	    }
319	    if (vpol == HYBRID_V_DRAIN_OK) {
320	        s.flags |= HYBRID_FLAG_V;
321	        /* The policy guarantees vlenb <= HYBRID_VLEN_BYTES_MAX here, so the
322	         * full live register fits the wire-format slot -- no clamp (L11). */
323	        for (int i = 0; i < 32; i++)
324	            (void) read_reg_bytes(v->vreg[i],
325	                                  &s.vreg[(size_t) i * HYBRID_VLEN_BYTES_MAX],
326	                                  (size_t) s.vlenb);
327	    }
328	
329	    if (write_state_atomic(&s, outfile_path) != 0) {
330	        fprintf(stderr, "hybrid_handoff: failed to write state file\n");
331	        exit(2);
332	    }
333	    fprintf(stderr,
334	            "hybrid_handoff: drained state to %s (pc=%#" PRIx64 "), exiting\n",
335	            outfile_path, s.pc);
336	}
