338	static void on_handoff(unsigned int vcpu_idx, void *udata)
339	{
340	    const HandoffSite *site = (const HandoffSite *) udata;
341	    if (site->kind != HYBRID_HANDOFF_ENTER) return;
342	    // F14: suppress the atexit drain path now that we have a real trigger.
343	    drained_already = 1;
344	    // PC via translation-time vaddr+size; reading the gdbstub PC inside the
345	    // exec callback can lag the actual current insn when V instructions
346	    // retire just before the trigger (TCG defers PC writes for performance).
347	    drain_state_to_file(vcpu_idx, compute_handoff_pc(site), 0);
348	    // 200 == kExitHandoffToQemu in verilator/src/hybrid/exit_codes.hpp.
349	    // Distinguishes drain from workload completion (0) so the orchestrator
350	    // can decide the next spawn.
351	    exit(200);
352	}
