354	// F14: per-insn tick. Increments a global counter every retired insn so the
355	// drain-at-exit path can report a true retired-insn total (independent of
356	// QEMU's PMU semantics).
357	static void on_count_tick(unsigned int vcpu_idx, void *udata)
358	{
359	    (void) vcpu_idx;
360	    (void) udata;
361	    atexit_insn_count++;
362	}
363	
364	// F14: atexit drain. Fires when QEMU exits naturally (e.g. guest semihosting
365	// EXIT). The semihosting EXIT runs on the vCPU thread, so current_cpu is
366	// still set and qemu_plugin_read_register works. If any other trigger
367	// already drained, return immediately (drained_already guards against
368	// double drain). Inside an atexit handler, exit() is UB per C11 7.22.4.4;
369	// use _exit() to skip the rest of the atexit chain.
370	static void on_atexit(qemu_plugin_id_t id, void *udata)
371	{
372	    (void) id;
373	    (void) udata;
374	    if (drained_already) return;
375	    if (!drain_at_exit_mode) return;
376	    // pc=0 is a positive marker that the atexit path drained (no trigger).
377	    drain_state_to_file(0, 0, atexit_insn_count);
378	    fflush(stderr);
379	    _exit(200);
380	}
381	
382	// Per-insn tick for oracle exit-drain mode (verify_oracle F1). udata is this
383	// insn's HandoffSite. When armed (the exit boundary's own tick ran), this
384	// tick fires before its insn executes, so a drain here records the
385	// post-retire state of the boundary insn with pc = the dynamically-next
386	// insn's vaddr. drain_pc (when set) defers the drain to the tick whose vaddr
387	// matches vsim's actual halt pc, so both sides sample the same point.
388	static void on_oracle_tick(unsigned int vcpu_idx, void *udata)
389	{
390	    const HandoffSite *site = (const HandoffSite *) udata;
391	    if (oracle_armed
392	        && (!drain_pc_set || site->vaddr == drain_pc_arg)) {
393	        // Suppress the F14 atexit drain path now that we drained.
394	        drained_already = 1;
395	        drain_state_to_file(vcpu_idx, site->vaddr, 0);
396	        exit(200);
397	    }
398	    if (exit_pc_mode ? (site->vaddr == exit_pc_arg)
399	                     : (site->kind == HYBRID_HANDOFF_EXIT)) {
400	        oracle_armed = 1;
401	    }
402	}
