  if (!andes_verify_excluded(name) && andes_supported_csr(name)  \
      && wm_live(HYBRID_WM_M_EXT_BASE + HYBRID_WM_M_EXT_IDX_##field)) \
    cmp(r, name, ref.m_ext.field, got.m_ext.field);
    HYBRID_M_EXT_CSR_LIST(X)
#undef X
  }

  // L2C MMIO config (v5): the L2C Control Register round-trips (restored at
  // resume, re-read at drain), so compare its RW config bits (CEN, prefetch,
  // ECC, RAM timing). INITSTATUS[14] is a read-only status bit -- a real L2C
  // model drives it, QEMU's RAM stub does not -- so mask it to avoid a false
  // positive. Only the writable Control Register is verified; the read-only
  // Configuration Register and the volatile CCTL/error/counter registers are
  // captured but not restored, so they are not compared.
  if (ref.flags & HYBRID_FLAG_L2C) {
    const uint64_t rw_mask = ~(uint64_t{1} << 14);  // clear INITSTATUS[14]
    cmp(r, "l2c.ctrl",
        ref.l2c.reg[HYBRID_L2C_OFF_CONTROL / 8] & rw_mask,
        got.l2c.reg[HYBRID_L2C_OFF_CONTROL / 8] & rw_mask);
  }

  return r;
}

std::vector<std::string> unsupported_written_csrs(
    const hybrid_state_v1& st, const std::vector<std::string>& andes_supported) {
  std::vector<std::string> out;
  if (!(st.flags & HYBRID_FLAG_WRITE_MASK)) return out;  // pre-v6: no info
  if (andes_supported.empty()) return out;               // no engine info

  const auto supported = [&](std::string_view name) {
    for (const std::string& s : andes_supported)
      if (s == name) return true;
    return false;
  };
  const auto written = [&](int slot) {
    return hybrid_wm_test(st.write_mask, static_cast<unsigned>(slot)) != 0;
  };

  // Andes scalars. ucode is skipped: the plugin sets its bit unconditionally
  // (transport-always DSP flag), so it carries no real write information.
#define X(field, addr, name)                                              \
  if (std::string_view{name} != "ucode"                                   \
      && written(HYBRID_WM_ANDES_BASE + HYBRID_WM_ANDES_IDX_##field)      \
      && !supported(name))                                                \
    out.push_back(name);
  HYBRID_ANDES_CSR_LIST(X)
#undef X

  // PMA: one group marker each, matching the --describe list's convention.
  for (int i = 0; i < HYBRID_PMA_CFG_NUM; ++i)
    if (written(HYBRID_WM_PMACFG_BASE + i) && !supported("pmacfg")) {
      out.push_back("pmacfg");
      break;
    }
  for (int i = 0; i < HYBRID_PMA_ADDR_NUM; ++i)
    if (written(HYBRID_WM_PMAADDR_BASE + i) && !supported("pmaaddr")) {
      out.push_back("pmaaddr");
      break;
    }

#define X(field, addr, name)                                              \
  if (written(HYBRID_WM_M_EXT_BASE + HYBRID_WM_M_EXT_IDX_##field)         \
      && !supported(name))                                                \
    out.push_back(name);
  HYBRID_M_EXT_CSR_LIST(X)
#undef X

  return out;
}

std::string unsupported_written_warning(
    const hybrid_state_v1& st, const std::vector<std::string>& andes_supported,
    const std::string& engine_id) {
  const auto bad = unsupported_written_csrs(st, andes_supported);
  if (bad.empty()) return {};
  std::string names;
  for (const std::string& n : bad) {
    if (!names.empty()) names += ", ";
    names += n;
  }
  return "[andesim] warning: the program wrote CSRs engine " + engine_id +
         " does not implement: " + names +
         " (on this engine's silicon these writes would trap; the hybrid "
         "restore skipped them)\n";
}

void print_diff_report(const DiffReport& r) {
  for (const FieldDiff& d : r.diffs)
    std::printf("[state-diff] %s: ref=0x%llx got=0x%llx\n", d.field.c_str(),
                d.ref, d.got);
  if (r.ok()) {
    std::printf(
        "[state-diff] PASS: %d fields match (counters and passthrough CSRs "
        "excluded)\n",
        r.compared);
  } else {
    std::printf("[state-diff] FAIL: %zu mismatch(es) (%d fields compared)\n",
                r.diffs.size(), r.compared);
  }
}

}  // namespace andes_sim

